/* Layout: a filter bar over one long list of dialogs; each dialog is a row whose left stripe and pill carry its proposed route. */
:root {
  --bg: #f6f7f8;
  --surface: #ffffff;
  --fg: #1c2127;
  --muted: #5d6874;
  --line: #dde1e6;
  --accent: #2b6a8f;
  --show: #4f6b57;     --show-bg: #e6efe8;
  --msg: #2b5f9e;      --msg-bg: #e3ecf8;
  --answer: #6a4c93;   --answer-bg: #eee8f6;
  --drop: #a33a32;     --drop-bg: #f7e5e3;
  --unsure: #8a5a00;   --unsure-bg: #f8eed9;
  --na: #6b7580;       --na-bg: #eceef0;
  --font-body: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --bg: #14181c; --surface: #1b2026; --fg: #e3e7eb; --muted: #9aa5b1; --line: #2d353e; --accent: #7cb4d6;
  --show: #93b99d; --show-bg: #1f2c23; --msg: #8db6ea; --msg-bg: #1b2738; --answer: #bca3df; --answer-bg: #2a2236;
  --drop: #ec9890; --drop-bg: #3a2220; --unsure: #e2b45e; --unsure-bg: #352a14; --na: #a3adb8; --na-bg: #262c33;
  color-scheme: dark; } }
:root[data-theme="dark"] {
  --bg: #14181c; --surface: #1b2026; --fg: #e3e7eb; --muted: #9aa5b1; --line: #2d353e; --accent: #7cb4d6;
  --show: #93b99d; --show-bg: #1f2c23; --msg: #8db6ea; --msg-bg: #1b2738; --answer: #bca3df; --answer-bg: #2a2236;
  --drop: #ec9890; --drop-bg: #3a2220; --unsure: #e2b45e; --unsure-bg: #352a14; --na: #a3adb8; --na-bg: #262c33;
  color-scheme: dark; }

* { box-sizing: border-box; }
body { background: var(--bg); color: var(--fg); font-family: var(--font-body); font-size: 15px; line-height: 1.5; }
.wrap { max-width: 1180px; margin: 0 auto; padding-block: 28px 64px;
  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }
h1 { font-size: 26px; font-weight: 600; margin: 0 0 6px; text-wrap: balance; }
h2 { font-size: 17px; font-weight: 600; margin: 0 0 10px; }
.lede { color: var(--muted); max-width: 70ch; margin: 0 0 18px; }
.lede strong { color: var(--fg); }
code, .mono { font-family: var(--font-mono); font-size: 0.86em; }
code { background: var(--na-bg); padding: 0 4px; border-radius: 3px; overflow-wrap: anywhere; }

.findings { background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 14px 16px; margin: 0 0 20px; max-width: 900px; }
.findings ul { margin: 0; padding-left: 20px; display: grid; gap: 6px; }
.findings li { overflow-wrap: anywhere; }
.tag { display: inline-block; font-size: 11.5px; font-weight: 600; padding: 0 6px; border-radius: 4px; margin-right: 6px; vertical-align: 1px; }
.tag.run { color: var(--show); background: var(--show-bg); }
.tag.read { color: var(--unsure); background: var(--unsure-bg); }
.routes { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; margin: 0 0 22px; }
.route-card { all: unset; cursor: pointer; display: grid; gap: 2px; padding: 12px 14px; border-radius: 8px;
  background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--c); }
.route-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.route-card[aria-pressed="true"] { background: var(--cbg); }
.route-card .num { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--c); }
.route-card .name { font-weight: 600; }
.route-card .def { color: var(--muted); font-size: 13px; }

.bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; background: var(--bg);
  display: flex; flex-wrap: wrap; gap: 8px 12px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--line); }
body::before { content: ""; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); }
.bar input[type=search], .bar select { font: inherit; font-size: 14px; color: var(--fg); background: var(--surface);
  border: 1px solid var(--line); border-radius: 6px; padding: 6px 10px; min-width: 0; }
.bar input[type=search] { flex: 1 1 240px; }
.bar select { flex: 0 1 280px; }
.bar label.check { display: flex; gap: 6px; align-items: center; font-size: 14px; color: var(--muted); }
.bar .count { margin-left: auto; color: var(--muted); font-size: 14px; font-variant-numeric: tabular-nums; }
.bar input:focus-visible, .bar select:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

.group-head { margin: 26px 0 8px; display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap; }
.group-head h2 { margin: 0; }
.group-head .sub { color: var(--muted); font-size: 13px; }

.row { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 6px 18px; padding: 12px 14px; margin: 0 0 6px;
  background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--c); border-radius: 6px; }
.row .side { display: grid; align-content: start; gap: 6px; }
.pill { justify-self: start; font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 999px; color: var(--c); background: var(--cbg); }
.reach { font-size: 12px; color: var(--muted); }
.row .main { min-width: 0; display: grid; gap: 4px; }
.gist { font-weight: 500; overflow-wrap: anywhere; }
.meta { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 2px 10px; font-size: 13.5px; }
.meta dt { color: var(--muted); }
.meta dd { margin: 0; overflow-wrap: anywhere; }
.site { font-family: var(--font-mono); font-size: 12px; color: var(--muted); overflow-wrap: anywhere; }
.empty { padding: 30px; text-align: center; color: var(--muted); }

.gaps { margin-top: 40px; padding-top: 18px; border-top: 1px solid var(--line); }
.gaps h3 { font-size: 14px; margin: 16px 0 4px; }
.gaps ul { margin: 0; padding-left: 20px; color: var(--muted); font-size: 14px; }
.gaps li { margin: 2px 0; overflow-wrap: anywhere; }

[data-route="SHOW"] { --c: var(--show); --cbg: var(--show-bg); }
[data-route="JUSPRIN-MESSAGE"] { --c: var(--msg); --cbg: var(--msg-bg); }
[data-route="ANSWER"] { --c: var(--answer); --cbg: var(--answer-bg); }
[data-route="DROP"] { --c: var(--drop); --cbg: var(--drop-bg); }
[data-route="UNSURE"] { --c: var(--unsure); --cbg: var(--unsure-bg); }
[data-route="n/a"] { --c: var(--na); --cbg: var(--na-bg); }

@media (max-width: 640px) {
  .row { grid-template-columns: minmax(0, 1fr); }
  .row .side { grid-auto-flow: column; justify-content: start; align-items: center; gap: 10px; }
  .meta { grid-template-columns: minmax(0, 1fr); }
  .meta dt { margin-top: 4px; }
  .bar .count { margin-left: 0; }
}
</style>

