bool AppMenus::run_shortcut(const wxKeyEvent& event)
{
    if (home() && wxGetApp().shortcuts().lookup(ShortcutContext::Global, KeyChord::from_event(event)) == Shortcut::ImportModel)
        return true;
    int id = 0;
    const int key = event.GetKeyCode();
    if (event.GetModifiers() == wxMOD_CMD) {
        if (key == 'N')
            id = m_new_project;
        else if (key == 'O')
            id = m_open;
        else if (key == 'S')
            id = m_save;
        else if (key == 'R')
            id = m_slice;
    } else if (event.GetModifiers() == (wxMOD_CMD | wxMOD_SHIFT) && key == 'S') {
        id = m_export_project;
    }
    if (id == 0)
        return false;
    run(id);
    return true;
}

